#ifndef RESET_CTRL_REGS_H
#define RESET_CTRL_REGS_H
#define RESET_CTRL_REGS_ID_OFFSET 0x00u
#define RESET_CTRL_REGS_VERSION_OFFSET 0x04u
#define RESET_CTRL_REGS_DATE_OFFSET 0x08u
#define RESET_CTRL_REGS_ID_VALUE 0x52535443u   /* "RSTC" */
#define RESET_CTRL_REGS_CTRL_OFFSET 0x10u   /* WO */
#define RESET_CTRL_REGS_CTRL_RESET 0x00000000u
#define RESET_CTRL_REGS_HOLD_OFFSET 0x14u   /* RW */
#define RESET_CTRL_REGS_STATUS_OFFSET 0x18u   /* CMD */
#define RESET_CTRL_REGS_STATUS_RESET 0x00000000u
#define RESET_CTRL_REGS_STATUS_ACTIVE_SHIFT 0u
#define RESET_CTRL_REGS_STATUS_ACTIVE_MASK 0x00000001u
#define RESET_CTRL_REGS_STATUS_EVENT_SHIFT 1u
#define RESET_CTRL_REGS_STATUS_EVENT_MASK 0x00000002u
#define RESET_CTRL_REGS_EVENT_COUNT_OFFSET 0x1Cu   /* RO */
#define RESET_CTRL_REGS_EVENT_COUNT_RESET 0x00000000u
#endif /* RESET_CTRL_REGS_H */
